import numpy as np
import os
import sys
import pdb
import argparse


# Column names of the per-tissue *_bootstrap_summary.txt files generated by run_ld_corr.py
output_names = ['calibration_slope', 'per_snp_eqtl_h2', 'borzoi_variance', 'unstandardized_borzoi_variance', 'correlation']


def extract_ld_corr_output_files(ld_corr_output_file_list):
	# Load list of per-tissue ld-corr output files (one file per line)
	ld_corr_output_files = []
	with open(ld_corr_output_file_list) as f:
		for line in f:
			line = line.rstrip()
			if line == '':
				continue
			if not os.path.isfile(line):
				raise ValueError('Per-tissue ld-corr output file does not exist: ' + line)
			ld_corr_output_files.append(line)
	if len(ld_corr_output_files) == 0:
		raise ValueError('No per-tissue ld-corr output files found in ' + ld_corr_output_file_list)
	return ld_corr_output_files


def load_single_tissue_results(ld_corr_output_file):
	# Map (annotation_name, category_name, sample_label, sample_iter) to vector of estimates
	# Also keep track of the order in which (annotation_name, category_name) pairs are observed
	key_to_estimates = {}
	ordered_anno_category_pairs = []
	observed_anno_category_pairs = {}

	head_count = 0
	with open(ld_corr_output_file) as f:
		for line in f:
			line = line.rstrip()
			data = line.split('\t')
			if head_count == 0:
				head_count = head_count + 1
				expected_header = ['annotation_name', 'category_name', 'sample_label', 'sample_iter'] + output_names
				if data != expected_header:
					raise ValueError('Unexpected header in ' + ld_corr_output_file + '. Expected:\n' + '\t'.join(expected_header))
				continue
			anno_name = data[0]
			category_name = data[1]
			sample_label = data[2]
			sample_iter = data[3]

			key = (anno_name, category_name, sample_label, sample_iter)
			if key in key_to_estimates:
				raise ValueError('Duplicate row for ' + str(key) + ' in ' + ld_corr_output_file)
			key_to_estimates[key] = np.asarray(data[4:]).astype(float)

			anno_category_pair = (anno_name, category_name)
			if anno_category_pair not in observed_anno_category_pairs:
				observed_anno_category_pairs[anno_category_pair] = 1
				ordered_anno_category_pairs.append(anno_category_pair)

	return key_to_estimates, ordered_anno_category_pairs


def meta_analyze_estimates(per_tissue_estimates, correlation_meta_method):
	# per_tissue_estimates is a (n_tissues X n_outputs) matrix
	# Average each output across tissues (ignoring tissues with missing estimates)
	if np.all(np.isnan(per_tissue_estimates)):
		return np.full(per_tissue_estimates.shape[1], np.nan)

	meta_analyzed_estimates = np.nanmean(per_tissue_estimates, axis=0)

	if correlation_meta_method == 'recompute_from_components':
		# Recompute correlation from the meta-analyzed components rather than averaging per-tissue correlations
		calibration_slope = meta_analyzed_estimates[0]
		per_snp_eqtl_h2 = meta_analyzed_estimates[1]
		borzoi_variance = meta_analyzed_estimates[2]
		sqrt_term = borzoi_variance/per_snp_eqtl_h2
		if np.isfinite(sqrt_term) and sqrt_term >= 0.0:
			meta_analyzed_estimates[4] = calibration_slope*np.sqrt(sqrt_term)
		else:
			meta_analyzed_estimates[4] = np.nan

	return meta_analyzed_estimates


#######################
# Command line args
#######################
parser = argparse.ArgumentParser()
parser.add_argument('--ld-corr-output-file-list', dest='ld_corr_output_file_list', default='None', type=str, help='File containing one per-tissue ld-corr *_bootstrap_summary.txt file per line')
parser.add_argument('--meta-analyzed-ld-corr-output-stem', dest='meta_analyzed_ld_corr_output_stem', default='None', type=str, help='Output file stem for the cross-tissue meta-analyzed results')
parser.add_argument('--correlation-meta-method', dest='correlation_meta_method', default='average_correlation', type=str, choices=['average_correlation', 'recompute_from_components'], help='How to meta-analyze the correlation: average the per-tissue correlations, or recompute it from the meta-analyzed components')
args = parser.parse_args()

ld_corr_output_file_list = args.ld_corr_output_file_list
meta_analyzed_ld_corr_output_stem = args.meta_analyzed_ld_corr_output_stem
correlation_meta_method = args.correlation_meta_method


##############################
# Load per-tissue results
##############################
ld_corr_output_files = extract_ld_corr_output_files(ld_corr_output_file_list)
print('Meta-analyzing ' + str(len(ld_corr_output_files)) + ' per-tissue ld-corr result files')

per_tissue_key_to_estimates = []
ordered_anno_category_pairs = None
for ld_corr_output_file in ld_corr_output_files:
	key_to_estimates, file_ordered_anno_category_pairs = load_single_tissue_results(ld_corr_output_file)
	per_tissue_key_to_estimates.append(key_to_estimates)
	# Use the annotation/category ordering from the first file
	if ordered_anno_category_pairs is None:
		ordered_anno_category_pairs = file_ordered_anno_category_pairs


##############################
# Meta-analyze across tissues
##############################
# Bootstrap iterations are shared across tissues (same resampled gene set each iteration),
# so tissues can be averaged within a bootstrap iteration to get a meta-analyzed bootstrap distribution
ordered_sample_keys = []
observed_sample_keys = {}
for key in per_tissue_key_to_estimates[0].keys():
	sample_key = (key[2], key[3])
	if sample_key not in observed_sample_keys:
		observed_sample_keys[sample_key] = 1
		ordered_sample_keys.append(sample_key)


meta_analyzed_key_to_estimates = {}
for anno_name, category_name in ordered_anno_category_pairs:
	for sample_label, sample_iter in ordered_sample_keys:
		key = (anno_name, category_name, sample_label, sample_iter)

		per_tissue_estimates = []
		for key_to_estimates in per_tissue_key_to_estimates:
			if key in key_to_estimates:
				per_tissue_estimates.append(key_to_estimates[key])
		if len(per_tissue_estimates) == 0:
			continue
		per_tissue_estimates = np.asarray(per_tissue_estimates)

		meta_analyzed_key_to_estimates[key] = meta_analyze_estimates(per_tissue_estimates, correlation_meta_method)

		# Flag annotations that are not present in every tissue (averaged over fewer tissues)
		if sample_label == 'observed' and per_tissue_estimates.shape[0] != len(ld_corr_output_files):
			print('WARNING: ' + anno_name + ':' + category_name + ' found in only ' + str(per_tissue_estimates.shape[0]) + ' of ' + str(len(ld_corr_output_files)) + ' tissues')


##############################
# Print meta-analyzed summary file (same format as the per-tissue summary files)
##############################
results_output_file = meta_analyzed_ld_corr_output_stem + '_bootstrap_summary.txt'
with open(results_output_file, 'w') as t:
	t.write('annotation_name\tcategory_name\tsample_label\tsample_iter\t' + '\t'.join(output_names) + '\n')
	for anno_name, category_name in ordered_anno_category_pairs:
		for sample_label, sample_iter in ordered_sample_keys:
			key = (anno_name, category_name, sample_label, sample_iter)
			if key not in meta_analyzed_key_to_estimates:
				continue
			estimates = meta_analyzed_key_to_estimates[key]
			t.write(anno_name + '\t' + category_name + '\t' + sample_label + '\t' + sample_iter + '\t' + '\t'.join(estimates.astype(str)) + '\n')


##############################
# Print meta-analyzed bootstrap stats file (same format as the per-tissue stats files)
##############################
summary_stats_output_file = meta_analyzed_ld_corr_output_stem + '_bootstrap_stats.txt'
with open(summary_stats_output_file, 'w') as t:
	t.write('annotation_name\tcategory_name\toutput_name\tmean\tbootstrapped_mean\tbootstrap_se\tgaussian_z_score\tempirical_ci_lower\tempirical_ci_upper\n')
	for anno_name, category_name in ordered_anno_category_pairs:
		observed_key = (anno_name, category_name, 'observed', '-1')
		if observed_key not in meta_analyzed_key_to_estimates:
			continue
		observed_estimates = meta_analyzed_key_to_estimates[observed_key]

		# Stack the meta-analyzed bootstrap iterations into an (n_bs X n_outputs) matrix
		bootstrap_estimates = []
		for sample_label, sample_iter in ordered_sample_keys:
			if sample_label != 'bootstrap':
				continue
			key = (anno_name, category_name, sample_label, sample_iter)
			if key in meta_analyzed_key_to_estimates:
				bootstrap_estimates.append(meta_analyzed_key_to_estimates[key])
		bootstrap_estimates = np.asarray(bootstrap_estimates)

		for output_iter, output_name in enumerate(output_names):
			bootstrap_distribution = bootstrap_estimates[:, output_iter]
			bootstrap_distribution = bootstrap_distribution[np.isfinite(bootstrap_distribution)]

			if len(bootstrap_distribution) < 2:
				bootstrap_mean = np.nan
				bootstrap_se = np.nan
				gaussian_z_score = np.nan
				empirical_ci = [np.nan, np.nan]
			else:
				bootstrap_mean = np.mean(bootstrap_distribution)
				bootstrap_se = np.std(bootstrap_distribution, ddof=1)
				if bootstrap_se == 0.0:
					gaussian_z_score = np.nan
				else:
					gaussian_z_score = observed_estimates[output_iter]/bootstrap_se
				empirical_ci = np.quantile(bootstrap_distribution, [.025, .975])

			t.write(anno_name + '\t' + category_name + '\t' + output_name + '\t' + str(observed_estimates[output_iter]) + '\t' + str(bootstrap_mean) + '\t' + str(bootstrap_se) + '\t' + str(gaussian_z_score) + '\t' + str(empirical_ci[0]) + '\t' + str(empirical_ci[1]) + '\n')

print(results_output_file)
print(summary_stats_output_file)
